    struct page *page;
    int i;

    /* Phase 1: Isolate pages and adjust count of unlocked pages */
    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        if (PageMlocked(page)) {
            ClearPageMlocked(page);
            zone->nr_mlock--;
        }
    }

    /* Phase 2: Release reference pins on pages not being unlocked */
    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        page_cache_release(page);
    }

    /* Phase 3: Putback pages that qualify for fast path */
    spin_lock(&zone->lock);
    for (i = 0; i < pvec->nr_pages; i++) {
