void unlock_pagevec(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;
    int unlock_count = 0;

    /* Phase 1: Isolate pages by checking if they are memory locked */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_count++;
        }
    }

    /* Phase 2: Release reference pins on pages not being unlocked */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (!PageLocked(page)) {
            put_page(page); // Release reference to avoid deadlocks
        }
    }

    /* Phase 3: Handle the putback of pages for fast path */
    if (unlock_count > 0) {
        spin_lock(&zone->lock);
        for (i = 0; i < pagevec_count(pvec); i++) {
            page = pvec->pages[i];
            if (PageLocked(page)) {
                unlock_page(page);
                page->flags &= ~PG_locked;
                __free_page(page); // Put back into the free list
            }
        }
        spin_unlock(&zone->lock);
    }

    pagevec_reinit(pvec);
}

