void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;
    int unlocked = 0;

    /* Phase 1: Isolate pages and adjust the count of unlocked pages */
    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_page(page);
            unlocked++;
        }
    }

    /* Phase 2: Release reference pins on pages not being unlocked */
    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (!PageLocked(page)) {
            put_page(page);
        }
    }

    /* Phase 3: Handle the putback of pages that qualified for a fast path */
    spin_lock(&zone->lock);
    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            putback_lru_page(page);
        }
    }
    spin_unlock(&zone->lock);

    pvec->nr = 0;
}
